# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PERİYODİK ÖZELLİKLERİ ETKİLEYEN İKİ TEMEL ETMEN VE ATOM YARIÇAPI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">TEMEL BELİRLEYİCİ ETMENLER (9.1.8.a)</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. Enerji Düzeyi (Katman / Periyot) Sayısı:</text>\n  <text x="50" y="114" font-size="10.5" fill="#1e40af">Yukarıdan aşağıya (aynı grupta) inildikçe katman</text>\n  <text x="50" y="128" font-size="10.5" fill="#1e40af">sayısı (n) artar; değerlik elektronları çekirdekten</text>\n  <text x="50" y="142" font-size="10.5" fill="#1e40af">uzaklaşır ve atom yarıçapı (hacmi) BÜYÜR.</text>\n  <text x="42" y="168" font-size="11.5" font-weight="bold" fill="#1e3a8a">2. Etkin Çekirdek Yükü (Çekirdek Çekim Gücü):</text>\n  <text x="50" y="186" font-size="10.5" fill="#1e40af">Soldan sağa (aynı periyotta) katman sayısı sabit</text>\n  <text x="50" y="200" font-size="10.5" fill="#1e40af">kalırken proton sayısı artar; etkin çekirdek çekimi</text>\n  <text x="50" y="214" font-size="10.5" fill="#1e40af">güçlendiği için atom yarıçapı KÜÇÜLÜR.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">ATOM YARIÇAPI DEĞİŞİMİ (KARDAN ADAM)</text>\n  <circle cx="430" cy="105" r="14" fill="#bbf7d0" stroke="#15803d" stroke-width="2"/>\n  <circle cx="430" cy="142" r="21" fill="#86efac" stroke="#15803d" stroke-width="2"/>\n  <circle cx="430" cy="192" r="29" fill="#4ade80" stroke="#15803d" stroke-width="2"/>\n  <text x="430" y="109" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">₂Li</text>\n  <text x="430" y="146" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">₁₁Na</text>\n  <text x="430" y="196" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">₁₉K</text>\n  <circle cx="515" cy="105" r="19" fill="#bbf7d0" stroke="#15803d" stroke-width="2"/>\n  <circle cx="575" cy="105" r="14" fill="#86efac" stroke="#15803d" stroke-width="2"/>\n  <circle cx="625" cy="105" r="10" fill="#4ade80" stroke="#15803d" stroke-width="2"/>\n  <text x="515" y="136" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#14532d">₁₁Na</text>\n  <text x="575" y="136" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#14532d">₁₂Mg</text>\n  <text x="625" y="136" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#14532d">₁₇Cl</text>\n  <text x="565" y="172" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Aynı Grupta ↓ : Yarıçap ARTAR</text>\n  <text x="565" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Aynı Periyotta → : Yarıçap AZALIR</text>\n  <text x="565" y="218" text-anchor="middle" font-size="10.5" fill="#14532d">Önce katman sayısına, eşitse protona bakılır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BİRİNCİ İYONLAŞMA ENERJİSİ GRAFİĞİ VE 3 UYUŞMAZLIK (2A>3A, 5A>6A)</text>\n  <rect x="25" y="45" width="355" height="195" rx="10" fill="#ffffff" stroke="#94a3b8" stroke-width="1.5"/>\n  <line x1="60" y1="210" x2="360" y2="210" stroke="#334155" stroke-width="2"/>\n  <line x1="60" y1="210" x2="60" y2="60" stroke="#334155" stroke-width="2"/>\n  <text x="210" y="232" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#334155">Atom Numarası (Aynı Periyot: 1A → 8A)</text>\n  <polyline points="75,190 110,145 145,162 180,130 215,95 250,115 285,80 325,62" fill="none" stroke="#dc2626" stroke-width="2.5"/>\n  <circle cx="75" cy="190" r="4" fill="#1d4ed8"/>\n  <circle cx="110" cy="145" r="4.5" fill="#dc2626"/>\n  <circle cx="145" cy="162" r="4" fill="#1d4ed8"/>\n  <circle cx="180" cy="130" r="4" fill="#1d4ed8"/>\n  <circle cx="215" cy="95" r="4.5" fill="#dc2626"/>\n  <circle cx="250" cy="115" r="4" fill="#1d4ed8"/>\n  <circle cx="285" cy="80" r="4" fill="#1d4ed8"/>\n  <circle cx="325" cy="62" r="4.5" fill="#16a34a"/>\n  <text x="75" y="205" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e3a8a">1A</text>\n  <text x="110" y="135" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#dc2626">2A</text>\n  <text x="145" y="178" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e3a8a">3A</text>\n  <text x="180" y="120" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e3a8a">4A</text>\n  <text x="215" y="85" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#dc2626">5A</text>\n  <text x="250" y="130" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e3a8a">6A</text>\n  <text x="285" y="72" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e3a8a">7A</text>\n  <text x="325" y="56" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#16a34a">8A</text>\n  <rect x="395" y="45" width="280" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="535" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">İYONLAŞMA ENERJİSİ SIRALAMASI</text>\n  <text x="410" y="94" font-size="11" font-weight="bold" fill="#7f1d1d">Aynı Periyotta (Üç Aşağı Beş Yukarı):</text>\n  <text x="410" y="114" font-size="11.5" font-weight="bold" fill="#b91c1c">1A &lt; 3A &lt; 2A &lt; 4A &lt; 6A &lt; 5A &lt; 7A &lt; 8A</text>\n  <text x="410" y="140" font-size="10.5" fill="#7f1d1d">• 2A &gt; 3A ve 5A &gt; 6A olmasının nedeni:</text>\n  <text x="418" y="156" font-size="10.5" fill="#7f1d1d">2A (tam dolu) ve 5A (yarı dolu) gruplarının</text>\n  <text x="418" y="172" font-size="10.5" fill="#7f1d1d">küresel simetri kararlılığına sahip olmasıdır.</text>\n  <text x="410" y="198" font-size="10.5" font-weight="bold" fill="#7f1d1d">• 8A\'dan bir sonraki periyodun 1A grubuna</text>\n  <text x="418" y="214" font-size="10.5" font-weight="bold" fill="#7f1d1d">geçilirken İE keskin bir düşüş gösterir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PERİYODİK ÖZELLİKLERİN DEĞİŞİM YÖNLERİ (BÜTÜNCÜL HARİTA)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">SOLDAN SAĞA (AYNI PERİYOTTA →)</text>\n  <text x="42" y="96" font-size="11" font-weight="bold" fill="#581c87">• Katman sayısı DEĞİŞMEZ, proton sayısı ARTAR.</text>\n  <text x="42" y="120" font-size="11" font-weight="bold" fill="#dc2626">• Atom yarıçapı (hacmi) AZALIR.</text>\n  <text x="42" y="144" font-size="11" font-weight="bold" fill="#16a34a">• İyonlaşma enerjisi GENELLİKLE ARTAR.</text>\n  <text x="42" y="168" font-size="11" font-weight="bold" fill="#16a34a">• Elektronegatiflik ARTAR (8A hariç, en yüksek 7A).</text>\n  <text x="42" y="192" font-size="11" font-weight="bold" fill="#16a34a">• Ametalik özellik ARTAR, metalik özellik AZALIR.</text>\n  <text x="42" y="216" font-size="10.5" fill="#6b21a8">En elektronegatif element: ₉F (Flor = 4,0)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">YUKARIDAN AŞAĞIYA (AYNI GRUPTA ↓)</text>\n  <text x="377" y="96" font-size="11" font-weight="bold" fill="#7c2d12">• Katman sayısı ve atom numarası ARTAR.</text>\n  <text x="377" y="120" font-size="11" font-weight="bold" fill="#16a34a">• Atom yarıçapı (hacmi) ARTAR.</text>\n  <text x="377" y="144" font-size="11" font-weight="bold" fill="#dc2626">• İyonlaşma enerjisi KESİNLİKLE AZALIR.</text>\n  <text x="377" y="168" font-size="11" font-weight="bold" fill="#dc2626">• Elektronegatiflik AZALIR.</text>\n  <text x="377" y="192" font-size="11" font-weight="bold" fill="#16a34a">• Metalik aktiflik ARTAR, ametalik aktiflik AZALIR.</text>\n  <text x="377" y="216" font-size="10.5" fill="#9a3412">İE sıçraması (≥ 3,5 - 4 kat) A grubu numarasını verir!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
